const fs=require("fs");
const p=JSON.parse(fs.readFileSync("apps/studio/package.json"));
const l=JSON.parse(fs.readFileSync("apps/studio/package-lock.json"));
const root=l.packages[""];
let bad=[];
for (const sec of ["dependencies","devDependencies"]) {
  for (const [k,v] of Object.entries(p[sec]||{})) {
    if (!root[sec] || root[sec][k]!==v) bad.push(`${sec}:${k} pkg=${v} lock=${root[sec]?.[k]}`);
  }
}
console.log(bad.length?bad.join("\n"):"package.json and package-lock.json root specs match");
'

